                        CoreCheckResult(
                            passed=False,
                            check="coords",
                            reason_code=(
                                SchemaErrorReason.COLUMN_NOT_IN_DATAFRAME
                            ),
                            message=(f"missing coordinate {cn!r}"),
                            failure_cases=cn,
