                                check="coords",
                                reason_code=(
                                    SchemaErrorReason.COLUMN_NOT_IN_DATAFRAME
                                ),
                                message=(f"missing coordinate {cn!r}"),
                                failure_cases=cn,
                            )
                        )
                elif isinstance(cspec, Coordinate):
                    results.extend(
                        da_backend._validate_coord_on_parent(
                            ds,
                            cn,
                            cspec,
